const vTr=(()=>{const V={'अ':'a','आ':'a','इ':'i','ई':'i','उ':'u','ऊ':'u','ए':'e','ऐ':'ai','ओ':'o','औ':'au','ऑ':'o','ऋ':'ri'},M={'ा':'a','ि':'i','ी':'i','ु':'u','ू':'u','े':'e','ै':'ai','ो':'o','ौ':'au','ॉ':'o','ं':'n','ँ':'n','ः':'h'},C={'क':'k','ख':'kh','ग':'g','घ':'gh','च':'ch','छ':'chh','ज':'j','झ':'jh','ट':'t','ठ':'th','ड':'d','ढ':'dh','ण':'n','त':'t','थ':'th','द':'d','ध':'dh','न':'n','प':'p','फ':'f','ब':'b','भ':'bh','म':'m','य':'y','र':'r','ल':'l','व':'v','श':'sh','ष':'sh','स':'s','ह':'h','ड़':'r','ढ़':'rh','क़':'k','ख़':'kh','ग़':'g','ज़':'j','फ़':'f'};
 return t=>{t=String(t||'').normalize('NFC').replace(/़/g,'');let o='';const a=[...t];for(let i=0;i<a.length;i++){const ch=a[i],nx=a[i+1];if(C[ch]!==undefined){o+=C[ch];if(nx==='्'){i++;continue}if(nx&&M[nx]!==undefined&&nx!=='ं'&&nx!=='ँ'&&nx!=='ः')continue;if(!nx||/\s/.test(nx)||nx===','||(nx==='ं'||nx==='ँ'||nx==='ः')&&false)continue;o+='a'}else if(M[ch]!==undefined)o+=M[ch];else if(V[ch]!==undefined)o+=V[ch];else o+=ch}return o.toLowerCase()}})();
