  sg.forEach(w=>{const l=vTr(w).replace(/[^a-z0-9.]/g,'');if(/^\d+(\.\d+)?$/.test(l)&&qty==null){qty=+l;return}if(VN[l]!==undefined&&qty==null){qty=VN[l];return}if(VU[l]&&!su&&(qty!=null||nm.length===0)){su=VU[l];return}nm.push(w)});
