  const o={heard,qty,su,it:bs>=.6?best:null};
  if(o.it){const u=o.it.unit;if(su==='kg')o.q=u==='g'?qty*1000:qty;else if(su==='g')o.q=u==='kg'?qty/1000:qty;else if(su==='L')o.q=u==='ml'?qty*1000:qty;else o.q=qty;o.q=+(+o.q).toFixed(3)}
