A.cancelbill=t=>ask('Cancel this bill? Stock and Udhaar will be restored.','Yes, cancel bill',()=>{const b=fb(+t.dataset.id);b.items.forEach(l=>{const it=D.items.find(x=>x.id===l.id);if(it)it.stock=+(it.stock+l.qty).toFixed(3)});const c=D.cust.find(x=>x.id===b.cust);if(c)c.bal=r2(c.bal-dueOf(b));D.bills=D.bills.filter(x=>x!==b);ARCH=ARCH.filter(x=>x!==b);saveArch();save();toast('Bill cancelled');go(cur)});
