V.ochk=()=>`<div class="c"><h3>Online order ke rate check karo</h3><div class="mu" style="margin-bottom:8px">Customer ka WhatsApp order yahan paste karo. App aapke asli rate se milayega aur batayega agar kisi ne rate badla ho.</div><textarea id="oc-t" class="in" rows="9" placeholder="*New Order* — ..." style="width:100%"></textarea><button class="btn" data-a="ochk">Check karo</button><div id="oc-r"></div></div>`;
let OCL=[];
const pnum=x=>+String(x).replace(/[₹,*\s]/g,'')||0;
A.ochk=()=>{const t=($('#oc-t').value||'').split('\n').map(x=>x.trim()),out=[];
 for(let n=0;n<t.length;n++){const m=/^\d+\.\s*(.+)$/.exec(t[n]),d=t[n+1]&&/^([\d.]+)\s*(\S+)\s*[×x]\s*₹?\s*([\d,.]+)\s*=\s*\*?₹?\s*([\d,.]+)/.exec(t[n+1]);if(m&&d)out.push({name:m[1].trim(),q:+d[1],u:d[2],p:pnum(d[3]),tot:pnum(d[4])})}
 const gm=/Grand Total:\s*\*?₹?\s*([\d,.]+)/i.exec(t.join('\n')),gt=gm?pnum(gm[1]):0;
 if(!out.length){$('#oc-r').innerHTML='<div class="mu" style="margin-top:10px;color:var(--rd)">Order samajh nahi aaya. Poora order message paste karo.</div>';return}
 let real=0,bad=0;OCL=[];
 const rows=out.map(o=>{const it=D.items.find(x=>x.name.toLowerCase()===o.name.toLowerCase()||(x.name+(x.size?' '+x.size:'')).toLowerCase()===o.name.toLowerCase());
  if(!it){bad++;return`<div class="row"><div class="nm"><b>${esc(o.name)}</b><span class="mu" style="color:var(--rd)">Aapki list mein nahi mila</span></div><b>${R(o.tot)}</b></div>`}
  const ok=Math.abs(it.price-o.p)<0.005,lt=Math.abs(o.p*o.q-o.tot)<0.5;real+=it.price*o.q;if(!ok||!lt)bad++;OCL.push({it,q:o.q});
  return`<div class="row"><div class="nm"><b>${esc(o.name)}</b><span class="mu" style="color:${ok&&lt?'var(--gn,#1a7f37)':'var(--rd)'}">${ok?'Rate sahi ('+R(it.price)+')':'Rate badla hua: order mein '+R(o.p)+', asli '+R(it.price)}${lt?'':' · jod galat'}</span></div><b>${R(it.price*o.q)}</b></div>`}).join('');
 const gok=!gt||Math.abs(gt-real)<1;
 $('#oc-r').innerHTML=`<div class="c" style="margin-top:12px">${rows}</div><div class="hero" style="margin-top:10px"><div class="mu">Asli total (aapke rate se)</div><b style="font-size:24px">${R(real)}</b>${gt?`<div class="mu" style="color:${gok?'var(--gn,#1a7f37)':'var(--rd)'}">Order mein total: ${R(gt)} ${gok?'(sahi)':'(alag hai!)'}</div>`:''}</div>${bad?'<div class="mu" style="margin-top:8px;color:var(--rd)">Dhyaan: '+bad+' line mein gadbad hai. Asli rate se hi bill banao.</div>':''}${OCL.length?`<button class="btn g" data-a="ocadd" style="margin-top:10px">Asli rate se cart mein jodo</button>`:''}`};
A.ocadd=()=>{OCL.forEach(o=>{const it=o.it,l=cart.find(c=>c.id===it.id);if(l)l.qty=+(l.qty+o.q).toFixed(3);else cart.push({id:it.id,name:it.size?it.name+' · '+it.size:it.name,price:it.price,cost:it.cost,gst:it.gst,unit:it.unit,quick:it.quick,qty:o.q})});const n=OCL.length;OCL=[];go('bill');toast(n+' item cart mein jod diye')};
