/* ===== EXPENSES ===== */
V.exp=()=>{const m=new Date();m.setDate(1);const mo=D.exp.filter(e=>e.ts>=day0(+m));return`<div class="hero"><div class="mu">This month's expenses</div><b style="font-size:26px">${R(sum(mo,'amt'))}</b></div><button class="btn" data-a="newexp" style="margin:0 0 12px">+ Add expense</button><div class="c">${D.exp.length?[...D.exp].reverse().slice(0,60).map(e=>`<button class="row" data-a="delexp" data-id="${e.id}"><div class="nm"><b>${esc(e.cat)}</b><span class="mu">${fd(e.ts)}${e.note?' · '+esc(e.note):''}</span></div><b>${R(e.amt)}</b></button>`).join(''):'<div class="mu">No expenses yet.</div>'}</div>`};
const ECAT=['Rent','Salary','Electricity','Transport','Stock purchase','Tea & snacks','Other'];let ecat='Rent';
A.newexp=()=>{ecat='Rent';sheet(`<h3>Add expense</h3><label>Amount (₹) *</label><input id="e-a" class="in" inputmode="decimal"><label>Category</label><div class="chips pay" style="margin-top:0">${ECAT.map(c=>`<button class="chip ${c===ecat?'on':''}" data-a="ecat" data-c="${c}">${c}</button>`).join('')}</div><label>Note (optional)</label><input id="e-n" class="in"><button class="btn" data-a="saveexp">Save expense</button>`)};
A.ecat=t=>{ecat=t.dataset.c;t.parentElement.querySelectorAll('.chip').forEach(b=>b.classList.toggle('on',b===t))};
A.saveexp=()=>{const a=mny($('#e-a').value);if(!(a>0))return toast('Enter amount');D.exp.push({id:uid(),amt:a,cat:ecat,note:txt($('#e-n').value,60),ts:Date.now()});save();closeSheet();toast('Expense saved');go(cur)};
A.delexp=t=>ask('Delete this expense?','Yes, delete',()=>{D.exp=D.exp.filter(x=>x.id!==+t.dataset.id);save();go(cur)});
/* ===== REPORTS ===== */
let rp='7';
V.reports=()=>{const d=repData(),{B,sales,pr,ex,top,pm,days,n}=d,mx=Math.max(...days.map(q=>q[1]),1),tm=top.length?top[0][1].a:1;
 const ch=rp!=='today'?`<div class="c"><h3>Daily sales</h3><div class="bar">${days.map(q=>{const g=new Date(q[0]).getDay();return`<i style="height:${Math.max(2,q[1]/mx*100)}%;--c1:${BC2[g][0]};--c2:${BC2[g][1]}"></i>`}).join('')}</div><div class="bl">${days.map((q,i)=>`<i>${n<=7||i%5===0?new Date(q[0]).getDate():''}</i>`).join('')}</div></div>`:'';
 return`<div class="chips" style="margin:0 0 12px">${[['today','Today'],['7','7 days'],['30','30 days'],['month','This month'],['all','All saved']].map(([k,l])=>`<button class="chip ${rp===k?'on':''}" data-a="rpt" data-k="${k}">${l}</button>`).join('')}</div>
 <div class="g2"><div class="c st gr"><b>${R(sales)}</b><span>Sales · ${B.length} bills</span></div><div class="c st mr"><b>${R(pr)}</b><span>Gross profit</span></div><div class="c st rd"><b>${R(ex)}</b><span>Expenses</span></div><div class="c st ${pr-ex>=0?'gr':'rd'}"><b>${R(pr-ex)}</b><span>Net profit</span></div></div>${ch}
 <div class="c"><h3>Top selling items</h3>${top.length?top.slice(0,5).map(([nm,v],i)=>`<div class="row"><div class="nm"><b>${esc(nm)}</b><span class="mu">${+v.q.toFixed(2)} sold</span><div class="tb"><i style="width:${Math.max(4,v.a/tm*100)}%;background:${PAL[i%8]}"></i></div></div><b>${R(v.a)}</b></div>`).join(''):'<div class="mu">No sales in this period.</div>'}</div>
 <div class="c"><h3>Money received by mode</h3>${pmBar(pm)}${Object.entries(pm).map(([k,v],i)=>`<div class="tl"><span>${esc(k)}</span><b>${R(v)}</b></div>`).join('')||'<div class="mu">—</div>'}${D.shop.gst?`<div class="tl mu"><span>GST collected</span><span>${R(sum(B,'tax'))}</span></div>`:''}</div>
 ${tipsHtml(d)}
 <button class="btn" data-a="expm">Export colourful report (PDF)</button>`};
A.rpt=t=>{rp=t.dataset.k;go('reports')};
A.csvb=()=>dl('bills.csv',csv([['Bill','Date','Customer','Subtotal','Discount','Tax','Total','Mode','Paid','Due'],...allB().map(b=>[bno(b),new Date(b.ts).toLocaleString('en-IN'),cname(b.cust)||'Walk-in',b.sub,b.disc,b.tax.toFixed(2),b.total,b.pay,b.paid,dueOf(b)])]),'text/csv');
A.csvi=()=>dl('items.csv',csv([['Name','Price','Cost','Stock','Unit','GST','Barcode'],...D.items.map(i=>[i.name,i.price,i.cost,i.stock,i.unit,i.gst,i.bc])]),'text/csv');
