const BC2=[['#f59e2b','#e8730c'],['#34c759','#138808'],['#d9534f','#7a1230'],['#4d94ff','#1f6feb'],['#ffd166','#d9a21b'],['#b46be0','#8e44ad'],['#3ed6b5','#16a085']],PAL=['#e8730c','#138808','#7a1230','#1f6feb','#d9a21b','#8e44ad','#16a085','#d32f2f'];
const FB='Inter,"Segoe UI",Roboto,"Noto Sans",Arial,sans-serif',FT=FB,FN=FB,FC='"Brush Script MT","Dancing Script","Segoe Script",cursive';
const RPL={today:'Today','7':'Last 7 days','30':'Last 30 days',month:'This month',all:'All saved bills'};
function repData(){const T=day0(),mo=new Date();mo.setDate(1);const from={today:T,'7':T-6*864e5,'30':T-29*864e5,month:day0(+mo),all:0}[rp],ALL=allB(),B=ALL.filter(b=>b.ts>=from),E=D.exp.filter(e=>e.ts>=from),sales=sum(B,'total'),pr=sum(B,bprofit),ex=sum(E,'amt'),m={};
 B.forEach(b=>b.items.forEach(i=>{const q=m[i.name]=m[i.name]||{q:0,a:0};q.q+=i.qty;q.a+=i.price*i.qty}));const top=Object.entries(m).sort((a,b)=>b[1].a-a[1].a).slice(0,8),pm={};B.forEach(b=>pm[b.pay]=(pm[b.pay]||0)+b.paid);
 const n=rp==='today'?1:rp==='all'||rp==='month'?30:+rp,days=[];for(let k=n-1;k>=0;k--){const s=T-k*864e5;days.push([s,sum(ALL.filter(b=>b.ts>=s&&b.ts<s+864e5),'total')])}
 return{T,from,ALL,B,E,sales,pr,ex,m,top,pm,days,n,due:sum(D.cust,c=>Math.max(0,c.bal)),disc:sum(B,'disc'),gst:sum(B,'tax')}}
function tipsOf(d){const t=[],{B,sales,pr,due,disc}=d,WD=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
 if(!B.length)return[['#1f6feb','Make more bills','Insights appear after you save a few bills. Try to bill every sale, even the small ones.'],['#138808','Add your items first','Add the items you sell with their cost price, so profit is calculated correctly.']];
 const mg=sales?pr/sales*100:0;
 if(mg<12)t.push(['#d32f2f','Profit margin is low ('+mg.toFixed(1)+'%)','Check cost prices and raise the price of fast-moving items by Rs 1-2. Small hikes add up fast.']);else if(mg>=25)t.push(['#138808','Healthy profit margin ('+mg.toFixed(1)+'%)','Keep it up. Keep your high-margin items near the counter and recommend them.']);
 const nc=D.items.filter(i=>!(i.cost>0)).length;if(nc)t.push(['#d9a21b',nc+' item'+(nc>1?'s have':' has')+' no cost price','Profit is not exact until the cost price is filled. Open Items and add it.']);
 const low=D.items.filter(i=>i.stock<=i.low);if(low.length)t.push(['#e8730c',low.length+' item'+(low.length>1?'s are':' is')+' low on stock','Reorder soon: '+low.slice(0,4).map(i=>i.name).join(', ')+(low.length>4?'...':'')+'. Empty shelves lose sales.']);
 if(due>0&&sales&&due/sales>.25)t.push(['#7a1230','Udhaar is high ('+R(due)+')','Send WhatsApp reminders every week and ask for part payment on each new Udhaar.']);
 const tc=D.cust.filter(c=>c.bal>0).sort((a,b)=>b.bal-a.bal)[0];if(tc)t.push(['#8e44ad','Biggest Udhaar: '+tc.name+' ('+R(tc.bal)+')','Message this customer first. Clearing one big account frees cash quickly.']);
 const dd=sales?disc/sales*100:0;if(dd>5)t.push(['#16a085','Discounts are '+dd.toFixed(1)+'% of sales','Give discount only on bulk buying. A fixed rule protects your profit.']);
 if(d.n>=14){const w=[0,0,0,0,0,0,0],c=[0,0,0,0,0,0,0];d.days.forEach(x=>{const g=new Date(x[0]).getDay();w[g]+=x[1];c[g]++});const av=w.map((v,i)=>c[i]?v/c[i]:0),hi=av.indexOf(Math.max(...av)),lo=av.indexOf(Math.min(...av));if(av[hi]>0&&av[lo]<av[hi]*.6)t.push(['#1f6feb',WD[lo]+' is your slowest day','Try a small offer or a "free delivery" message on '+WD[lo]+'. '+WD[hi]+' is your best day, so stock up for it.'])}
 const sold=new Set();d.ALL.filter(b=>b.ts>=d.T-29*864e5).forEach(b=>b.items.forEach(i=>sold.add(i.id)));const dead=D.items.filter(i=>!sold.has(i.id)&&i.stock>0).length;if(dead>3&&d.ALL.length>10)t.push(['#1f6feb',dead+' items did not sell in 30 days','Put them on offer or stop restocking them. Dead stock blocks your money.']);
 const soon=D.items.filter(i=>i.exp&&(new Date(i.exp)-Date.now())/864e5<=15).length;if(soon)t.push(['#d32f2f',soon+' item'+(soon>1?'s expire':' expires')+' within 15 days','Sell them first or give a combo offer, so nothing is wasted.']);
 if(!D.bk||Date.now()-D.bk>TEN)t.push(['#7a1230','Take a backup today','Your data lives on this phone. Save a backup file or use Google Drive backup.']);
 if(!D.shop.upi)t.push(['#1f6feb','Add your UPI ID','Customers pay faster when your UPI ID is on the bill. Add it in Settings.']);
 if(t.length<3)t.push(['#138808','Share your Store Link','Customers can see your items and send orders on WhatsApp. Share it from More > Share.']);
 return t.slice(0,7)}
const pmBar=pm=>{const e=Object.entries(pm).filter(x=>x[1]>0),tot=e.reduce((a,x)=>a+x[1],0);if(!tot)return'';return`<div class="pmb">${e.map(([k,v],i)=>`<i style="width:${v/tot*100}%;background:${PAL[i%8]}"></i>`).join('')}</div><div class="pml">${e.map(([k,v],i)=>`<span style="--pc:${PAL[i%8]}">${esc(k)} ${Math.round(v/tot*100)}%</span>`).join('')}</div>`};
const tipsHtml=d=>`<div class="c"><h3>How we can improve</h3>${tipsOf(d).map(([c,h,s])=>`<div class="tp" style="--tc:${c}"><i></i><div><b>${esc(h)}</b><span>${esc(s)}</span></div></div>`).join('')}<button class="btn o" data-a="sugg">Suggest a feature or improvement</button></div>`;
/* --- canvas helpers --- */
const rr=(x,X,Y,W,H,r)=>{x.beginPath();x.moveTo(X+r,Y);x.arcTo(X+W,Y,X+W,Y+H,r);x.arcTo(X+W,Y+H,X,Y+H,r);x.arcTo(X,Y+H,X,Y,r);x.arcTo(X,Y,X+W,Y,r);x.closePath()};
const tx=(x,t,X,Y,f,c,al='left')=>{x.font=f;x.fillStyle=c;x.textAlign=al;x.fillText(t,X,Y)};
function wrapT(x,t,X,Y,W,lh,f,c){x.font=f;x.fillStyle=c;x.textAlign='left';let l='',n=0;for(const w of String(t).split(' ')){const q=l?l+' '+w:w;if(x.measureText(q).width>W&&l){x.fillText(l,X,Y+n*lh);n++;l=w}else l=q}x.fillText(l,X,Y+n*lh);return n+1}
const clip=(x,t,W,f)=>{x.font=f;t=String(t);if(x.measureText(t).width<=W)return t;while(t.length>1&&x.measureText(t+'..').width>W)t=t.slice(0,-1);return t+'..'};
const pgNew=()=>{const c=document.createElement('canvas');c.width=1190;c.height=1684;const x=c.getContext('2d');x.scale(2,2);x.fillStyle='#fffaf0';x.fillRect(0,0,595,842);return[c,x]};
