 card(x,30,566,260,225);tx(x,'Money received',46,592,'bold 17px '+FT,'#7a1230');
 const e=Object.entries(d.pm).filter(q=>q[1]>0),tot=e.reduce((a,q)=>a+q[1],0),cx=110,cy=690,R1=52;
 if(tot){let a0=-Math.PI/2;e.forEach(([k,v],i)=>{const a1=a0+v/tot*Math.PI*2;x.beginPath();x.moveTo(cx,cy);x.arc(cx,cy,R1,a0,a1);x.closePath();x.fillStyle=PAL[i%8];x.fill();a0=a1});x.beginPath();x.arc(cx,cy,28,0,7);x.fillStyle='#fff';x.fill();tx(x,'Total',cx,cy-2,'10px '+FB,'#85705c','center');tx(x,R(tot),cx,cy+12,'bold 11px '+FN,'#7a1230','center');
  e.slice(0,6).forEach(([k,v],i)=>{const Y=620+i*26;x.fillStyle=PAL[i%8];x.beginPath();x.arc(190,Y-4,5,0,7);x.fill();tx(x,clip(x,k,60,'12px '+FB),200,Y,'12px '+FB,'#2b1a10');tx(x,R(v),274,Y+13,'bold 10px '+FN,'#5b4636','right')})}
 else tx(x,'No money received yet',46,640,'13px '+FB,'#85705c');
 card(x,305,566,260,225,'#fff9e8');tx(x,'Quick facts',321,592,'bold 17px '+FT,'#7a1230');
 const F=[['Bills',d.B.length+'','#e8730c'],['Average bill',R(d.B.length?d.sales/d.B.length:0),'#138808'],['Udhaar given',R(sum(d.B,b=>Math.max(0,dueOf(b)))),'#7a1230'],['Total Udhaar pending',R(d.due),'#d32f2f'],['Discount given',R(d.disc),'#8e44ad'],['GST collected',R(d.gst),'#1f6feb']];
