function mkPdf(pages){const E=s=>new TextEncoder().encode(s),parts=[],off=[];let len=0;const push=u=>{parts.push(u);len+=u.length},obj=(n,b)=>{off[n]=len;push(E(n+' 0 obj\n'));push(typeof b==='string'?E(b):b);push(E('\nendobj\n'))};
 push(E('%PDF-1.4\n'));const N=pages.length;obj(1,'<</Type/Catalog/Pages 2 0 R>>');obj(2,`<</Type/Pages/Count ${N}/Kids[${pages.map((_,i)=>(3+i*3)+' 0 R').join(' ')}]>>`);
 pages.forEach((p,i)=>{const pg=3+i*3,ct=pg+1,im=pg+2,cs='q 595 0 0 842 0 0 cm /I Do Q';obj(pg,`<</Type/Page/Parent 2 0 R/MediaBox[0 0 595 842]/Resources<</XObject<</I ${im} 0 R>>>>/Contents ${ct} 0 R>>`);obj(ct,`<</Length ${cs.length}>>\nstream\n${cs}\nendstream`);
  off[im]=len;push(E(`${im} 0 obj\n<</Type/XObject/Subtype/Image/Width ${p.w}/Height ${p.h}/ColorSpace/DeviceRGB/BitsPerComponent 8/Filter/DCTDecode/Length ${p.d.length}>>\nstream\n`));push(p.d);push(E('\nendstream\nendobj\n'))});
 const xr=len,T=3+N*3;let x='xref\n0 '+T+'\n0000000000 65535 f \n';for(let i=1;i<T;i++)x+=String(off[i]).padStart(10,'0')+' 00000 n \n';x+='trailer\n<</Size '+T+'/Root 1 0 R>>\nstartxref\n'+xr+'\n%%EOF';push(E(x));return new Blob(parts,{type:'application/pdf'})}
