async function outPdf(cv,name){toast('PDF ban rahi hai…',3000);await new Promise(r=>setTimeout(r,80));const imgs=cv.map(c=>({d:bk64d(c.toDataURL('image/jpeg',.9).split(',')[1]),w:c.width,h:c.height})),blob=mkPdf(imgs),f=new File([blob],name,{type:'application/pdf'});
 if(navigator.canShare&&navigator.canShare({files:[f]})){try{await navigator.share({files:[f],title:name});return}catch(e){if(e&&e.name==='AbortError')return}}
 const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),4e4);toast('PDF saved to your downloads')}
