const bk64e=u=>{let t='';for(let i=0;i<u.length;i+=8192)t+=String.fromCharCode.apply(null,u.subarray(i,i+8192));return btoa(t)},bk64d=t=>Uint8Array.from(atob(t),c=>c.charCodeAt(0));
async function bkKey(pw,salt){const k=await crypto.subtle.importKey('raw',new TextEncoder().encode(pw),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:310000,hash:'SHA-256'},k,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function bkEnc(txt,pw){const sl=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),k=await bkKey(pw,sl),ct=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv},k,new TextEncoder().encode(txt)));return JSON.stringify({_enc:1,v:1,s:bk64e(sl),i:bk64e(iv),d:bk64e(ct)})}
async function bkDec(o,pw){const k=await bkKey(pw,bk64d(o.s));return new TextDecoder().decode(await crypto.subtle.decrypt({name:'AES-GCM',iv:bk64d(o.i)},k,bk64d(o.d)))}
