 const st=p.s==='pro'?`Pro plan active (${PN[p.pl]})${ex}`:p.s==='trial'?`Free trial: ${p.left} day${p.left>1?'s':''} left · all Pro features on`:p.s==='free'?`Free plan · ${FREE_ITEMS} items · ${FREE_CUST} Udhaar customers · no Drive backup`:`Not logged in · Free plan limits apply`;
