let scS,scT,busy=false,hold=false,lastC='',lastT=0,aCtx,missC='';
function beep(ok=true){try{aCtx.resume();const o=aCtx.createOscillator(),g=aCtx.createGain();o.frequency.value=ok?1040:300;o.connect(g);g.connect(aCtx.destination);g.gain.setValueAtTime(.15,aCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,aCtx.currentTime+.18);o.start();o.stop(aCtx.currentTime+.18)}catch{}}
function stopScan(){clearInterval(scT);scS&&scS.getTracks().forEach(t=>t.stop());scS=null;busy=false;hold=false;lastC='';$('#sq').classList.add('hide');$('#scn').classList.add('hide')}
