function sInfo(m,bad){$('#sm').innerHTML=m;$('#sm').style.color=bad?'var(--rd)':'var(--gr)';$('#sn2').textContent=cart.length+' items';$('#st2').textContent=R(T().total)}
function qItem(c,n,p,k){const q=D.quick[c]||{};return{id:'q'+c,name:n||q.name||('Item '+c.slice(-4)),price:p||q.price||0,cost:k!=null?k:(q.cost||0),gst:0,unit:'pcs',bc:c,quick:1}}
function scanHit(c){if(typeof c!=='string'||!c)return;try{scanHit2(c)}catch{try{busy=false;hold=false}catch{}toast('Could not read this barcode')}}
function scanHit2(c){let it=D.items.find(i=>i.bc===c);if(!it&&D.quick[c])it=qItem(c);
 if(it){addCart(it);beep();sInfo(esc(it.name)+' · '+R(it.price)+(it.quick?' (quick item)':''))}
 else{beep(false);missC=c;hold=true;$('#sqm').textContent='New barcode '+c+' · enter name & price';$('#sq-n').value='';$('#sq-p').value='';$('#sq-c').value='';$('#sq').classList.remove('hide');$('#sinfo').classList.add('hide');setTimeout(()=>$('#sq-n').focus(),150);lookBc(c)}}
async function lookBc(c){const sh=()=>missC===c&&!$('#sq').classList.contains('hide'),nm=$('#sq-n'),ch=BCC[c];
 if(ch&&sh()&&!nm.value){nm.value=ch.n;$('#sqm').textContent='Saved name found · enter the price';$('#sq-p').focus();return}
 if(!/^\d{8,14}$/.test(c))return;
 if(!navigator.onLine){if(sh())$('#sqm').textContent='Offline · enter name and price';return}
 $('#sqm').textContent='New barcode '+c+' · looking up name…';
 try{const ac=new AbortController(),t=setTimeout(()=>ac.abort(),3000);const r=await fetch('https://world.openfoodfacts.org/api/v2/product/'+c+'.json?fields=product_name,brands,quantity',{signal:ac.signal,referrerPolicy:'no-referrer',credentials:'omit'});clearTimeout(t);if(!r.ok)throw 0;const j=await r.json(),pr=j&&j.status===1&&j.product;
  if(pr){const n=[pr.brands&&String(pr.brands).split(',')[0],pr.product_name,pr.quantity].filter(Boolean).join(' ').trim().slice(0,60);if(n){bcPut(c,n);if(sh()&&!nm.value){nm.value=n;$('#sqm').textContent='Name found · enter the price';$('#sq-p').focus();return}}}}catch{}
 if(sh())$('#sqm').textContent='New barcode '+c+' · enter name and price (one time only)'}
A.sundo=()=>{const l=cart[cart.length-1];if(!l)return;l.qty=+(l.qty-1).toFixed(3);if(l.qty<=0)cart.pop();cartR();sInfo('Last item removed')};
A.sqadd=()=>{const p=mny($('#sq-p').value);if(!(p>0))return toast('Enter selling price');if(p>1e6)return toast('Price must be below ₹10,00,000');const n=txt($('#sq-n').value,60),k=Math.max(0,mny($('#sq-c').value));D.quick[missC]={name:n||('Item '+missC.slice(-4)),price:p,cost:k};if(n)bcPut(missC,n);save();addCart(qItem(missC,n,p,k));beep();$('#sq').classList.add('hide');$('#sinfo').classList.remove('hide');sInfo(esc(D.quick[missC].name)+' · '+R(p));lastC=missC;lastT=Date.now();hold=false};
