/* ===== CASH TALLY / GULLA CHECK ===== */
const DEN=[500,200,100,50,20,10],dk=()=>new Date().toLocaleDateString('en-CA');
function tExp(){const T=day0(),B=allB().filter(b=>b.ts>=T&&b.ts<T+DAY&&bOK(b));return{cs:sum(B.filter(b=>b.pay==='Cash'||b.pay==='Udhaar'),'paid'),rc:sum(D.pay.filter(p=>p.ts>=T&&p.ts<T+DAY&&p.mode==='Cash'),'amt'),ex:sum(D.exp.filter(e=>e.ts>=T&&e.ts<T+DAY),'amt')}}
const tMsg=d=>Math.abs(d)<.5?'Cash matched':d<0?`${R(-d)} short`:`${R(d)} excess`;
V.tally=()=>{const e=tExp(),k=dk(),sv=D.tally[k],pv=Object.keys(D.tally).filter(x=>x<k).sort().pop(),op=sv?sv.open:(pv?D.tally[pv].cnt:0),nt=sv?sv.notes:{};
 return`<div class="c"><h3>Today's expected cash (as per app)</h3><label>Opening cash (₹)</label><input id="t-o" class="in" inputmode="decimal" placeholder="0" value="${op||''}">
 <div class="tl" style="margin-top:8px"><span>+ Cash sales</span><b>${R(e.cs)}</b></div><div class="tl"><span>+ Udhaar collected (cash)</span><b>${R(e.rc)}</b></div><div class="tl"><span>− Cash expenses</span><b>${R(e.ex)}</b></div><div class="tl t"><span>Expected cash in drawer</span><span id="t-ex"></span></div></div>
 <div class="c"><h3>Cash count · physical notes</h3>${DEN.map(d=>`<div class="tr"><b>₹${d}</b><input id="t${d}" class="in" inputmode="numeric" placeholder="0" value="${nt[d]||''}"><span class="la" id="tp${d}"></span></div>`).join('')}<div class="tr"><b>Coins</b><input id="tc" class="in" inputmode="decimal" placeholder="₹ total" value="${nt.c||''}"><span></span></div>
 <div class="tl t"><span>Counted total</span><span id="t-ct"></span></div><div id="t-res" class="res"></div><label>Note (optional)</label><input id="t-n" class="in" placeholder="e.g. ₹50 short due to change" value="${esc(sv&&sv.note||'')}"><button class="btn big g" data-a="tsave">Save Today's Tally</button></div>
 <div class="c"><h3>Previous tallies</h3>${Object.keys(D.tally).sort().reverse().slice(0,10).map(k=>{const t=D.tally[k];return`<div class="row"><div class="nm"><b>${esc(k)}</b><span class="mu">Counted ${R(t.cnt)}${t.note?' · '+esc(t.note):''}</span></div><span class="bg ${Math.abs(t.diff)<.5?'':'d'}">${Math.abs(t.diff)<.5?'Matched':(t.diff<0?'−':'+')+R(Math.abs(t.diff))}</span></div>`}).join('')||'<div class="mu">No tally saved yet.</div>'}</div>`};
function tVals(){const n={};let c=0;DEN.forEach(d=>{const q=Math.max(0,Math.floor(num($('#t'+d).value)));n[d]=q;c+=q*d;$('#tp'+d).textContent=q?R(q*d):''});n.c=Math.max(0,mny($('#tc').value));return{n,c:r2(c+n.c)}}
function tR(){const e=tExp(),v=tVals(),ex=r2(mny($('#t-o').value)+e.cs+e.rc-e.ex),r=$('#t-res');$('#t-ex').textContent=R(ex);$('#t-ct').textContent=R(v.c);
 if(!v.c){r.className='res';r.textContent='Enter the counted cash';return}const d=r2(v.c-ex);r.className='res '+(Math.abs(d)<.5?'ok':'bad');r.textContent=tMsg(d)}
after.tally=()=>{$('#main').querySelectorAll('input').forEach(i=>i.oninput=tR);tR()};
