function calcEval(s){const t=String(s).replace(/×/g,'*').replace(/÷/g,'/').replace(/−/g,'-').match(/\d+\.?\d*|\.\d+|[-+*/%()]/g);if(!t)return NaN;let p=0;
 const prim=()=>{const x=t[p++];if(x==='('){const r=expr();if(t[p]===')')p++;return r}if(x==='-')return{v:-prim().v};if(x==='+')return prim();const v=parseFloat(x);if(isNaN(v))throw 0;return{v}},
 post=()=>{let r=prim();while(t[p]==='%'){p++;r={v:r.v/100,pct:1}}return r},
 term=()=>{let a=post();while(t[p]==='*'||t[p]==='/'){const o=t[p++],b=post();a={v:o==='*'?a.v*b.v:a.v/b.v}}return a},
 expr=()=>{let a=term();while(t[p]==='+'||t[p]==='-'){const o=t[p++],b=term(),bv=b.pct?a.v*b.v:b.v;a={v:o==='+'?a.v+bv:a.v-bv}}return a};
 try{const r=expr();return p<t.length?NaN:r.v}catch{return NaN}}
